with valid_inventory as (select *, case when quantity >= 212 then 'High' when quantity >= 51 then 'Medium' else 'Low' end quantity_band from inventory where store_id in (2, 6) and store_id in (1, 2, 3, 6)), inventory_stats as (select store_id, product_id, count(distinct quantity) unique_stores, min(quantity) min_quantity from valid_inventory group by store_id, product_id) select * from inventory_stats order by store_id, product_id limit 1;
